insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-math-036', '{"value":127,"tolerance":0}'::jsonb, '305 − 178: 305 − 100 = 205, 205 − 70 = 135, 135 − 8 = 127.', null, '[{"value":273,"why":"273 comes from subtracting the smaller digit from the larger in each column; you need to regroup (borrow)."}]'::jsonb),
  ('pri-math-037', '"a"'::jsonb, 'Look at the tens digit: 6 is 5 or more, so round the hundreds up. 49 hundreds becomes 50 hundreds = 5,000.', '{"b":"The tens digit is 6, so round up, not down.","c":"4,000 is rounding to the nearest thousand, and rounding down.","d":"4,960 is rounded to the nearest ten."}'::jsonb, null),
  ('pri-math-038', '{"value":1000,"tolerance":0}'::jsonb, '125 × 8 = (100 × 8) + (25 × 8) = 800 + 200 = 1,000.', null, '[{"value":133,"why":"133 adds 8; the question multiplies by 8."}]'::jsonb),
  ('pri-math-039', '["a","c","e"]'::jsonb, 'A factor divides exactly: 18 = 2 × 9 = 3 × 6, so 2, 6 and 9 are factors.', '{"b":"18 ÷ 4 = 4 remainder 2, so 4 is not a factor.","d":"18 ÷ 8 = 2 remainder 2, so 8 is not a factor."}'::jsonb, null),
  ('pri-math-040', '["b","a","d","c"]'::jsonb, 'Write them with three decimal places: 0.050, 0.500, 0.505, 0.550.', null, null),
  ('pri-math-041', '{"a":"y","b":"z","c":"x"}'::jsonb, '1/2 = 50/100 = 0.5, 1/4 = 25/100 = 0.25 and 3/4 = 75/100 = 0.75.', null, null),
  ('pri-math-042', '{"value":26,"tolerance":0,"unit":"cm"}'::jsonb, 'Perimeter is the distance all the way round: 8 + 5 + 8 + 5 = 26 cm.', null, '[{"value":40,"why":"40 cm² is the area (8 × 5); perimeter adds the four sides."},{"value":13,"why":"13 cm covers only two sides; a rectangle has four."}]'::jsonb),
  ('pri-math-043', '"a"'::jsonb, 'Make the denominators the same: 2/3 = 4/6. Then 4/6 + 1/6 = 5/6.', '{"b":"Never add the denominators: find a common denominator instead.","c":"2/3 equals 4/6, not 2/6.","d":"2/18 multiplies the fractions."}'::jsonb, null),
  ('pri-math-044', '{"value":15,"tolerance":0}'::jsonb, 'Add them and divide by how many there are: (12 + 15 + 18) ÷ 3 = 45 ÷ 3 = 15.', null, '[{"value":45,"why":"45 is the total; divide by 3 to share it equally."}]'::jsonb),
  ('pri-math-045', '"false"'::jsonb, 'A cube has 6 square faces, 12 edges and 8 vertices (corners).', '{"true":"8 is the number of corners (vertices). Count the flat square faces: there are 6, like a dice."}'::jsonb, null),
  ('pri-math-046', '{"value":90,"tolerance":0,"unit":"minutes"}'::jsonb, '9:45 to 10:45 is 60 minutes, and 10:45 to 11:15 is 30 more: 90 minutes.', null, '[{"value":130,"why":"Time is not like ordinary subtraction: 1115 − 945 = 170 ignores that an hour has 60 minutes, not 100."},{"value":70,"why":"Count again: 9:45 → 10:45 is a full hour, then 30 more minutes."}]'::jsonb),
  ('pri-math-047', '{"value":0.06,"tolerance":0.0001}'::jsonb, '3 × 2 = 6. There are two decimal places in total (one in each number), so the answer is 0.06.', null, '[{"value":0.6,"why":"Count the decimal places: 0.3 and 0.2 have one each, so the answer has two: 0.06."}]'::jsonb),
  ('pri-math-048', '"a"'::jsonb, 'Mass is measured in grams and kilograms. An apple is light, about 150 grams.', '{"b":"Kilometres measure long distances.","c":"Litres measure volume of liquid.","d":"Centimetres measure length."}'::jsonb, null),
  ('pri-math-049', '{"value":30,"tolerance":0,"unit":"RM"}'::jsonb, '10% of RM150 is RM15, so 20% is RM30.', null, '[{"value":120,"why":"RM120 is the price after the discount; the question asks for the discount itself."},{"value":20,"why":"20% means 20 out of every 100, so for RM150 it is RM30."}]'::jsonb),
  ('pri-math-050', '{"accept":["cube","a cube"]}'::jsonb, 'A cube has 6 equal square faces, like a dice.', null, null),
  ('pri-sci-026', '"a"'::jsonb, 'Jupiter is the biggest planet: more than 1,000 Earths could fit inside it.', '{"b":"Earth is much smaller than the giant planets.","c":"Saturn is the second largest.","d":"Mars is smaller than Earth."}'::jsonb, null),
  ('pri-sci-027', '"true"'::jsonb, 'Green plants use sunlight, water and carbon dioxide to make their food (sugar) in their leaves.', '{"false":"Without light, green plants cannot make food; that is why plants kept in the dark turn yellow and weak."}'::jsonb, null),
  ('pri-sci-028', '["a","c"]'::jsonb, 'Salt and sugar break up into tiny pieces you cannot see and mix evenly with the water: they dissolve.', '{"b":"Sand sinks to the bottom; it does not dissolve.","d":"Pebbles stay whole at the bottom.","e":"Oil floats on top in a separate layer."}'::jsonb, null),
  ('pri-sci-029', '["b","c","a"]'::jsonb, 'Heating melts ice into liquid water, and more heating boils the water into steam.', null, null),
  ('pri-sci-030', '{"a":"y","b":"z","c":"x"}'::jsonb, 'We see with our eyes, hear with our ears and smell with our nose.', null, null),
  ('pri-sci-031', '"a"'::jsonb, 'Chickens are birds, and all birds lay eggs.', '{"b":"Cows give birth to live young (calves).","c":"Cats give birth to live kittens.","d":"Goats give birth to live kids."}'::jsonb, null),
  ('pri-sci-032', '"a"'::jsonb, 'Nocturnal animals are active at night. Many have big eyes or excellent hearing to find food in the dark.', '{"b":"Diurnal animals are active during the day, like us.","c":"Herbivores are plant-eaters; that is about food, not time of day.","d":"Migratory animals travel long distances with the seasons."}'::jsonb, null),
  ('pri-sci-033', '{"accept":["nectar"]}'::jsonb, 'Bees drink nectar from flowers and turn it into honey. While visiting, they carry pollen from flower to flower.', null, null),
  ('pri-sci-034', '{"value":6,"tolerance":0}'::jsonb, 'All insects have 6 legs and 3 body parts (head, thorax and abdomen).', null, '[{"value":8,"why":"8 legs belong to spiders and scorpions (arachnids), which are not insects."}]'::jsonb),
  ('pri-sci-035', '"a"'::jsonb, 'The Earth spins once every 24 hours. The side facing the Sun has day; the side facing away has night.', '{"b":"One trip around the Sun takes a year, not a day.","c":"The Moon blocking the Sun is a solar eclipse, which is rare.","d":"The Sun only seems to move across the sky because the Earth is spinning."}'::jsonb, null),
  ('pri-sci-036', '"true"'::jsonb, 'Electricity needs an unbroken path from the battery, through the bulb and back. A gap (like an open switch) stops the flow.', '{"false":"Any gap breaks the path, so no electricity flows and the bulb stays off. That is how a switch works."}'::jsonb, null),
  ('pri-sci-037', '["a","c","e"]'::jsonb, 'Metals such as copper, iron and aluminium conduct electricity. That is why wires are made of copper.', '{"b":"Rubber is an insulator; it is used to cover wires and keep us safe.","d":"Plastic is an insulator."}'::jsonb, null),
  ('pri-sci-038', '"a"'::jsonb, 'After pollination, the flower develops into a fruit with seeds inside.', '{"b":"Roots take in water and hold the plant in place.","c":"The stem holds the plant up and carries water.","d":"Leaves make food using sunlight."}'::jsonb, null),
  ('pri-sci-039', '["c","a","d","b"]'::jsonb, 'Eggs hatch into tadpoles that breathe with gills; tadpoles grow legs and become froglets, then adult frogs.', null, null),
  ('pri-sci-040', '"a"'::jsonb, 'Air is about 78% nitrogen and 21% oxygen, with small amounts of other gases.', '{"b":"Oxygen is about 21% of the air: important, but not the most.","c":"Carbon dioxide is less than 1% of the air.","d":"There is hardly any hydrogen in the air."}'::jsonb, null),
  ('pri-eng-021', '"a"'::jsonb, 'Nouns ending in -x, -s, -sh, -ch or -z add -es: box → boxes, bus → buses.', '{"b":"Words ending in -x need -es, not just -s.","c":"\"Boxen\" is not standard English.","d":"-ies is for words ending in a consonant + y, like baby → babies."}'::jsonb, null),
  ('pri-eng-022', '"a"'::jsonb, '"Every Saturday" shows a habit, so we use the present simple. With he, she, it or one person (my brother), add -s: he plays.', '{"b":"\"Play\" is used with I, you, we and they.","c":"\"Playing\" needs a helper verb: he is playing.","d":"\"Played\" is the past tense, but \"every Saturday\" describes a habit now."}'::jsonb, null),
  ('pri-eng-023', '["a","b"]'::jsonb, 'Adjectives describe nouns. "Small" and "brown" describe the dog.', '{"c":"\"Dog\" is a noun: the thing being described.","d":"\"Barked\" is a verb: the action.","e":"\"Loudly\" is an adverb: it describes how the dog barked."}'::jsonb, null),
  ('pri-eng-024', '["b","c","a","d"]'::jsonb, 'A statement starts with the subject (My cat), then the verb (is sleeping): My cat is sleeping.', null, null),
  ('pri-eng-025', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Synonyms mean the same: big – large, quick – fast, little – small.', null, null),
  ('pri-eng-026', '"true"'::jsonb, 'Proper nouns name a particular person, place or thing, and always start with a capital letter.', '{"false":"Names of people, places, days and months are proper nouns, and they always need a capital letter."}'::jsonb, null),
  ('pri-eng-027', '"a"'::jsonb, 'Sunflower = sun + flower.', '{"b":"\"Happy\" is a single word.","c":"\"Running\" is run + -ing, an ending, not a second word.","d":"\"Beautiful\" is beauty + -ful, a suffix, not two words."}'::jsonb, null),
  ('pri-eng-028', '{"accept":["swam"]}'::jsonb, '"Swim" is irregular: swim → swam → swum. Yesterday, we swam in the pool.', null, null),
  ('pri-eng-029', '"a"'::jsonb, 'Prepositions show where or when something is: under, on, in, behind, before.', '{"b":"\"Quickly\" is an adverb.","c":"\"Happy\" is an adjective.","d":"\"Jump\" is a verb."}'::jsonb, null),
  ('pri-eng-030', '{"accept":["late"]}'::jsonb, 'The opposite of early is late: "I woke up early, but my brother woke up late."', null, null),
  ('pri-bm-001', '"a"'::jsonb, 'Lawan bagi "tinggi" ialah "rendah". Contoh: Bangunan itu tinggi, tetapi rumah saya rendah.', '{"b":"Lawan bagi \"besar\" ialah \"kecil\".","c":"Lawan bagi \"panjang\" ialah \"pendek\".","d":"Lawan bagi \"jauh\" ialah \"dekat\"."}'::jsonb, null),
  ('pri-bm-002', '"a"'::jsonb, '"Gembira" dan "suka" mempunyai maksud yang sama, iaitu berasa senang hati.', '{"b":"\"Sedih\" ialah lawan bagi \"gembira\".","c":"\"Marah\" bermaksud berasa berang, bukan senang hati.","d":"\"Letih\" bermaksud penat."}'::jsonb, null),
  ('pri-bm-003', '{"accept":["buah"]}'::jsonb, 'Penjodoh bilangan bagi rumah ialah "buah": sebuah rumah, sebuah kereta.', null, null),
  ('pri-bm-004', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Seekor kucing (haiwan), seorang guru (manusia), sebiji bola (benda kecil yang bulat).', null, null),
  ('pri-bm-005', '"false"'::jsonb, 'Ayat ini memberi maklumat, jadi ia ialah ayat penyata. Ayat tanya digunakan untuk bertanya dan diakhiri dengan tanda soal (?).', '{"true":"Ayat tanya bertanya sesuatu, contohnya \"Apakah yang Ali makan?\". Ayat ini hanya menyatakan sesuatu."}'::jsonb, null),
  ('pri-gk-001', '{"value":7,"tolerance":0}'::jsonb, 'Red, orange, yellow, green, blue, indigo and violet: 7 colours. In reality the colours blend smoothly into each other.', null, '[{"value":6,"why":"Some lists leave out indigo, but the traditional count is seven."}]'::jsonb),
  ('pri-gk-002', '"a"'::jsonb, 'The red hibiscus, called bunga raya, has been Malaysia''s national flower since 1960.', '{"b":"The rose is a national flower of several other countries, not Malaysia.","c":"Orchids grow widely in Malaysia but are not the national flower.","d":"The lotus is associated with countries such as India and Vietnam."}'::jsonb, null),
  ('pri-gk-003', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Birds build nests, bees live in hives and spiders spin webs.', null, null),
  ('pri-gk-004', '["b","d","a","c"]'::jsonb, 'An ant is tiny, a cat is small, a horse is big and an elephant is the biggest land animal.', null, null),
  ('pri-gk-005', '"true"'::jsonb, 'The Sun is a star, a huge ball of hot glowing gas. It looks bigger and brighter than other stars because it is much closer to us.', '{"false":"The Sun is the nearest star to Earth. The stars we see at night are other suns, much farther away."}'::jsonb, null)
